function renderPalDropSection(pal:Pal){if(!itemData)return "";const byId=new Map(itemData.items.map(item=>[item.id,item])),drops=itemData.drops.filter(drop=>drop.palId===pal.id);if(!drops.length)return "";return `<section class="detail-section pal-drop-section"><h2>${dropLabels[locale].items}</h2><div class="relation-list entity-relation-list">${drops.map(drop=>{const item=byId.get(drop.itemId);return item?`<a href="${href(`/items/${encodeURIComponent(item.id)}`)}" data-link>${item.image?`<img src="/assets/items/${encodeURIComponent(item.id)}.webp" alt="" loading="lazy">`:""}<span><strong>${esc(itemName(item))}</strong>${dropFacts(drop)}</span></a>`:""}).join("")}</div></section>`}
function itemDropSources(item:Item){return groupItemDropSources(item.id,data?.pals||[],itemData?.drops||[])}
function renderItemDropSection(item:Item){const entries=itemDropSources(item);return `<section class="detail-section item-drop-section"><h2>${dropLabels[locale].pals}${entries.length?` · ${entries.length.toLocaleString(locale)}`:""}</h2>${entries.length?`<div class="relation-list entity-relation-list">${entries.map(({pal,drops})=>`<a href="${href(`/pals/${encodeURIComponent(pal.id)}`)}" data-link>${pal.image?`<img src="/assets/pals/${encodeURIComponent(pal.id)}.png" alt="" loading="lazy">`:""}<span><strong>#${pal.dex}${pal.variant?"B":""} ${esc(palName(pal))}</strong>${drops.map(drop=>dropFacts(drop)).join("")}</span></a>`).join("")}</div>`:`<p class="empty-compact">${esc(dropEmptyLabels[locale])}</p>`}</section>`}
