function workSuitabilityBadges(work:Work,compact=false){const metadata=new Map((data?.workSuitabilities||[]).map(entry=>[entry.id,entry]));return Object.entries(work).filter(([,level])=>level>0).sort((a,b)=>b[1]-a[1]||a[0].localeCompare(b[0])).map(([id,level])=>{const entry=metadata.get(id),label=entry?.names[locale]||entry?.names[defaultLocale]||id,accessible=`${label} ${level}`;return `<span class="work-suitability${compact?" compact":""}" title="${esc(accessible)}" aria-label="${esc(accessible)}"><img src="${esc(entry?.icon||`/assets/work-suitability/${id}.webp`)}" alt="" width="24" height="24"><span class="work-suitability-label">${esc(label)}</span><b>${level}</b></span>`}).join("")}
