function passiveSkillCard(skill:PassiveSkill,{compact=false,linked=true}={}){const localized=(names:Record<Locale,string>)=>names[locale]||names[defaultLocale],labels=passiveUiLabels[locale],name=localized(skill.names),description=localized(skill.descriptions),rankLabel=`${labels.rank} ${skill.rank>=0?"+":""}${skill.rank}`,inheritLabel=skill.randomInheritanceAllowed?labels.inheritable:labels.fixed,item=itemData?.items.find(entry=>entry.id===skill.surgeryRequiredItem),itemLabel=item?itemName(item):skill.surgeryRequiredItem?uiCopy[locale].loading:"";return `<article class="passive-card rank-${skill.rank<0?"negative":"positive"}" data-rank="${skill.rank}"><header class="passive-card-header"><span class="passive-card-title">${linked?`<a class="skill-name-link" href="${href(`/skills/passive/${encodeURIComponent(skill.id)}`)}" data-link>${esc(name)}</a>`:esc(name)}</span><span class="passive-card-icons"><span class="passive-status" title="${esc(rankLabel)}" aria-label="${esc(rankLabel)}"><img src="/assets/passive-ranks/${skill.rank}.png" alt="" width="24" height="24"></span><span class="passive-status" title="${esc(inheritLabel)}" aria-label="${esc(inheritLabel)}">${icon(skill.randomInheritanceAllowed?"inherit":"fixed")}</span>${skill.surgeryCost>0?`<span class="passive-status" title="${esc(labels.surgery)} ${skill.surgeryCost.toLocaleString(locale)}${itemLabel?` · ${esc(itemLabel)}`:""}" aria-label="${esc(labels.surgery)} ${skill.surgeryCost.toLocaleString(locale)}">${item?.image?`<img src="/assets/items/${encodeURIComponent(item.id)}.webp" alt="" width="24" height="24">`:icon("surgery")}</span>`:""}</span></header>${compact?"":`<p class="passive-card-description">${esc(description)}</p>`}</article>`}
function skillTabs(activeKind=""){const labels=skillLabels[locale],tabs:[string,string][]=[["",labels.all],["active",labels.active],["passive",labels.passive],["partner",partnerLabel[locale]]];return `<nav class="subnav" aria-label="${labels.title}">${tabs.map(([kind,label])=>`<a href="${href(kind?`/skills/${kind}`:"/skills")}" data-link class="${activeKind===kind?"active":""}">${label}</a>`).join("")}</nav>`}
function skillsCategoryPage(kind:"active"|"passive"|"partner"){if(kind==="partner"){const skills=skillData?.partnerSkills||[],pals=new Map(data?.pals.map(p=>[p.id,p])||[]);setMeta(partnerLabel[locale],partnerLabel[locale]);const cards=skills.map(skill=>{const pal=pals.get(skill.palId),name=partnerSkillName(skill,pal);if(!pal||!name)return "";return `<article class="skill-card partner-skill-card"><div class="skill-card-head">${pal.image?`<img src="/assets/pals/${encodeURIComponent(pal.id)}.png" alt="" width="56" height="56" loading="lazy">`:""}<div><h2><a class="skill-name-link" href="${href(`/skills/partner/${encodeURIComponent(skill.id)}`)}" data-link>${esc(name)}</a></h2><a class="partner-pal-link" href="${href(`/pals/${encodeURIComponent(pal.id)}`)}" data-link>${esc(palName(pal))}</a></div></div></article>`}).join("");return `${hero(partnerLabel[locale],partnerLabel[locale])}<section class="section">${skillTabs(kind)}${data?`<p role="status">${skills.length.toLocaleString(locale)} ${m.results}</p><div class="skill-grid">${cards}</div>`:""}</section>`}const html=skillsPage(kind==="passive"),labels=skillLabels[locale];setMeta(kind==="active"?labels.active:labels.passive,`${labels.active} · ${labels.passive}`);return `<div class="skill-category-${kind}">${html.replace('<section class="section">',`<section class="section">${skillTabs(kind)}`)}</div>`}

function routeStructuredData(title:string,description:string,canonical:string){const current=route(),isCollection=knownCollectionRoutes.has(current),safeDetail=current.match(/^\/database\/(npcs|dungeons|technology)\/[^/]+$/);let type:string|null=current==="/"?"WebSite":["/map","/calculators","/calculators/breeding","/calculators/crafting","/server-tools/settings-generator"].includes(current)?"WebApplication":isCollection?"CollectionPage":safeDetail?"WebPage":null;if(!type)return null;const page:Record<string,unknown>={"@type":type,name:title,url:canonical,description,inLanguage:locale};if(type==="WebApplication"){page.applicationCategory="GameApplication";page.operatingSystem="Any"}if(type==="WebSite")return {"@context":"https://schema.org",...page};if(!safeDetail)return {"@context":"https://schema.org","@graph":[page]};const family=safeDetail[1],parentPath=`/database/${family}`,parentLabel=family==="npcs"?npcCopy[locale].catalogTitle:family==="dungeons"?dungeonCopy[locale].title:technologyCopy[locale].title;return {"@context":"https://schema.org","@graph":[page,{"@type":"BreadcrumbList",itemListElement:[{"@type":"ListItem",position:1,name:m.home,item:`${site.origin}${href("/")}`},{"@type":"ListItem",position:2,name:parentLabel,item:`${site.origin}${href(parentPath)}`},{"@type":"ListItem",position:3,name:title,item:canonical}]}]}}
function setMeta(title:string,description=m.tagline){document.documentElement.lang=locale;document.title=`${title} · ${site.name}`;document.querySelectorAll("[data-dynamic-meta],[data-route-structured-data]").forEach(n=>n.remove());const canonical=`${site.origin}${href(route())}`,socialImage=`${site.origin}/og-image.png`;for(const [tag,attrs] of [["meta",{name:"description",content:description}],["link",{rel:"canonical",href:canonical}],["meta",{property:"og:type",content:"website"}],["meta",{property:"og:title",content:document.title}],["meta",{property:"og:description",content:description}],["meta",{property:"og:url",content:canonical}],["meta",{property:"og:image",content:socialImage}],["meta",{name:"twitter:card",content:"summary_large_image"}],["meta",{name:"twitter:title",content:document.title}],["meta",{name:"twitter:description",content:description}],["meta",{name:"twitter:image",content:socialImage}]] as const){const el=document.createElement(tag);Object.entries(attrs).forEach(([k,v])=>el.setAttribute(k,v));el.setAttribute("data-dynamic-meta","true");document.head.append(el)}for(const loc of locales){const el=document.createElement("link");el.rel="alternate";el.hreflang=loc;el.href=`${site.origin}${localizePath(loc,route())}`;el.dataset.dynamicMeta="true";document.head.append(el)}const alternate=document.createElement("link");alternate.rel="alternate";alternate.hreflang="x-default";alternate.href=`${site.origin}${localizePath(defaultLocale,route())}`;alternate.dataset.dynamicMeta="true";document.head.append(alternate);const structured=routeStructuredData(title,description,canonical);if(structured){const script=document.createElement("script");script.type="application/ld+json";script.dataset.routeStructuredData="true";script.textContent=JSON.stringify(structured).replace(/</g,"\\u003c");document.head.append(script)}}
const themeModeLabels:Record<Locale,[string,string,string]>={
  "en-US":["System","Light","Dark"],"ko-KR":["시스템","밝게","어둡게"],"ja-JP":["システム","ライト","ダーク"],"zh-CN":["跟随系统","浅色","深色"],"zh-TW":["跟隨系統","淺色","深色"],"de-DE":["System","Hell","Dunkel"],"fr-FR":["Système","Clair","Sombre"],"it-IT":["Sistema","Chiaro","Scuro"],"es-ES":["Sistema","Claro","Oscuro"],"es-419":["Sistema","Claro","Oscuro"],"pt-BR":["Sistema","Claro","Escuro"],"ru-RU":["Система","Светлая","Тёмная"],"id-ID":["Sistem","Terang","Gelap"],"th-TH":["ระบบ","สว่าง","มืด"],"tr-TR":["Sistem","Açık","Koyu"],"vi-VN":["Hệ thống","Sáng","Tối"],"pl-PL":["System","Jasny","Ciemny"]
};
const moreLabels:Record<Locale,string>={"en-US":"More","ko-KR":"더보기","ja-JP":"その他","zh-CN":"更多","zh-TW":"更多","de-DE":"Mehr","fr-FR":"Plus","it-IT":"Altro","es-ES":"Más","es-419":"Más","pt-BR":"Mais","ru-RU":"Ещё","id-ID":"Lainnya","th-TH":"เพิ่มเติม","tr-TR":"Daha fazla","vi-VN":"Thêm","pl-PL":"Więcej"};
const globalSearchLabels:Record<Locale,string>={"en-US":"Search all game data","ko-KR":"전체 게임 정보 검색","ja-JP":"ゲーム情報を検索","zh-CN":"搜索全部游戏数据","zh-TW":"搜尋全部遊戲資料","de-DE":"Alle Spieldaten suchen","fr-FR":"Rechercher toutes les données","it-IT":"Cerca in tutti i dati","es-ES":"Buscar en todos los datos","es-419":"Buscar en todos los datos","pt-BR":"Buscar em todos os dados","ru-RU":"Поиск по игровым данным","id-ID":"Cari semua data game","th-TH":"ค้นหาข้อมูลเกมทั้งหมด","tr-TR":"Tüm oyun verilerinde ara","vi-VN":"Tìm kiếm toàn bộ dữ liệu","pl-PL":"Przeszukaj wszystkie dane"};
type ShellNavItem=typeof shellNavigation[number];
function shellLabel(item:ShellNavItem){return item.id==="home"?m.home:item.id==="map"?m.map:item.id==="pals"?m.pals:item.id==="skills"?skillLabels[locale].title:item.id==="calculators"?m.calculators:item.id==="database"?m.database:m.server}
function isShellActive(item:ShellNavItem){const current=route(),target=`/${item.path}`.replace(/\/$/,"")||"/";return target==="/"?current==="/":current===target||current.startsWith(`${target}/`)||item.id==="calculators"&&current.startsWith("/calculators")}
function shellLink(item:ShellNavItem,compact=false){const active=isShellActive(item),label=shellLabel(item);return `<a href="${href(`/${item.path}`)}" data-link class="${active?"active":""}" ${active?'aria-current="page"':""}>${compact?icon(item.icon as IconName):""}<span>${label}</span></a>`}
function header(){const currentTheme=localStorage.getItem("pw-theme")||"system",[systemLabel,lightLabel,darkLabel]=themeModeLabels[locale];return `<header class="site-header"><a class="brand" href="${href("/")}" data-link><span class="brand-mark"><img src="/favicon.svg" alt="" width="34" height="34"></span><span>${site.name}</span></a><nav class="primary-nav" aria-label="${m.home}">${shellNavigation.map(item=>shellLink(item)).join("")}</nav><button class="header-search" type="button" data-open-search aria-haspopup="dialog">${icon("search")}<span>${globalSearchLabels[locale]}</span><kbd>/</kbd></button><div class="header-actions"><select id="locale" aria-label="${m.language}">${locales.map(l=>`<option value="${l}" ${l===locale?"selected":""}>${localeLabels[l]}</option>`).join("")}</select><details class="theme-menu"><summary class="icon-button" aria-label="${m.theme}">${icon(currentTheme==="light"?"sun":currentTheme==="dark"?"moon":"system")}</summary><div class="theme-options" role="group" aria-label="${m.theme}">${[["system","system",systemLabel],["light","sun",lightLabel],["dark","moon",darkLabel]].map(([mode,iconName,label])=>`<button type="button" data-theme-choice="${mode}" aria-pressed="${currentTheme===mode}">${icon(iconName as IconName)}<span>${label}</span></button>`).join("")}</div></details></div></header>`}
function mobileShell(){const primary=shellNavigation.slice(0,3);return `<nav class="mobile-nav" aria-label="${m.home}">${primary.map(item=>shellLink(item,true)).join("")}<button type="button" data-open-search>${icon("search")}<small>${m.search}</small></button><button type="button" data-open-more>${icon("more")}<small>${moreLabels[locale]}</small></button></nav>`}
function shellDialogs(){return `<dialog id="global-search-dialog" class="shell-dialog"><form method="dialog"><button class="dialog-close" value="cancel" aria-label="${m.remove}">${icon("close")}</button><label for="global-search-input">${globalSearchLabels[locale]}</label><div class="global-search-field">${icon("search")}<input id="global-search-input" type="search" autocomplete="off" placeholder="${globalSearchLabels[locale]}"><button type="button" data-clear-global-search aria-label="${m.remove}">${icon("close")}</button></div><p id="global-search-status" role="status"></p><div id="global-search-results" class="global-search-results"></div></form></dialog><dialog id="more-dialog" class="shell-dialog"><form method="dialog"><button class="dialog-close" value="cancel" aria-label="${m.remove}">${icon("close")}</button><strong>${moreLabels[locale]}</strong><nav class="more-nav" aria-label="${moreLabels[locale]}">${shellNavigation.map(item=>shellLink(item,true)).join("")}</nav></form></dialog>`}
function footer(){return `<footer><div><strong>${site.name}</strong><p>${m.footer}</p></div></footer>`}
const consentSafeBody:Record<Locale,string>={
  "en-US":"Optional analytics and advertising stay off unless you allow them. Search text and server settings are never sent.","ko-KR":"허용하기 전에는 선택적 분석 및 광고가 꺼져 있습니다. 검색어와 서버 설정은 전송하지 않습니다.","ja-JP":"許可するまで任意の分析と広告は無効です。検索語とサーバー設定は送信されません。","zh-CN":"在您允许前，可选分析和广告保持关闭。搜索文字和服务器设置绝不会被发送。","zh-TW":"在您允許前，選用分析與廣告會保持關閉。搜尋文字及伺服器設定絕不會被傳送。","fr-FR":"Les analyses et publicités facultatives restent désactivées sans votre accord. Les recherches et paramètres serveur ne sont jamais transmis.","it-IT":"Analisi e pubblicità facoltative restano disattivate finché non le autorizzi. Ricerche e impostazioni server non vengono mai inviate.","de-DE":"Optionale Analyse und Werbung bleiben ohne deine Zustimmung deaktiviert. Suchtexte und Servereinstellungen werden nie übertragen.","es-ES":"Los análisis y anuncios opcionales permanecen desactivados hasta que los permitas. Nunca se envían búsquedas ni ajustes del servidor.","pt-BR":"Análises e anúncios opcionais permanecem desativados até sua permissão. Buscas e configurações do servidor nunca são enviados.","ru-RU":"Необязательная аналитика и реклама отключены до вашего согласия. Поисковые запросы и настройки сервера никогда не отправляются.","id-ID":"Analitik dan iklan opsional tetap nonaktif sampai Anda mengizinkannya. Teks pencarian dan pengaturan server tidak pernah dikirim.","es-419":"Los análisis y anuncios opcionales permanecen desactivados hasta que los permitas. Nunca se envían búsquedas ni ajustes del servidor.","th-TH":"การวิเคราะห์และโฆษณาที่ไม่บังคับจะปิดอยู่จนกว่าคุณจะอนุญาต ระบบจะไม่ส่งข้อความค้นหาหรือการตั้งค่าเซิร์ฟเวอร์","tr-TR":"İzin verene kadar isteğe bağlı analiz ve reklamlar kapalı kalır. Arama metni ve sunucu ayarları asla gönderilmez.","vi-VN":"Phân tích và quảng cáo tùy chọn được tắt cho đến khi bạn cho phép. Nội dung tìm kiếm và cài đặt máy chủ không bao giờ được gửi đi.","pl-PL":"Opcjonalna analityka i reklamy pozostają wyłączone bez Twojej zgody. Wyszukiwania i ustawienia serwera nigdy nie są wysyłane."
};
function consentBanner(){if(!(site.analyticsId||site.adsenseClient)||localStorage.getItem("pw-consent"))return "";return `<aside class="consent" aria-label="${m.consentTitle}"><div><strong>${m.consentTitle}</strong><p>${consentSafeBody[locale]}</p></div><button class="button primary" data-consent="allow">${m.allow}</button><button class="button" data-consent="decline">${m.decline}</button></aside>`}
function hero(title:string,..._descriptions:string[]){return `<section class="page-hero"><p class="eyebrow">${m.verified}</p><h1>${title}</h1></section>`}
function home(){setMeta(m.hero,m.tagline);return `<section class="hero"><div class="hero-copy"><p class="eyebrow">${m.verified}</p><h1>${m.hero}</h1><p class="lede">${m.tagline}</p><div class="hero-actions"><a class="button primary" href="${href("/pals")}" data-link>${m.openPals}</a><a class="button" href="${href("/calculators/breeding")}" data-link>${m.openBreed}</a></div></div><div class="hero-art" aria-hidden="true"><div class="orbital one"></div><div class="orbital two"></div><div class="island i1"></div><div class="island i2"></div></div></section><section class="section">${site.adsenseClient&&site.adsenseContentSlot?`<div class="ad-slot" aria-label="${m.adReserved}" data-ad-slot="${esc(site.adsenseContentSlot)}">${m.adReserved}</div>`:""}</section>`}
function palCard(p:Pal){const search=[...Object.values(p.names),p.id,p.dex,...Object.keys(p.work).filter(k=>p.work[k]>0)].join(" ").toLocaleLowerCase(locale);return `<article class="pal-card" data-pal="${esc(search)}" data-rarity="${p.rarity}" data-work="${esc(Object.keys(p.work).filter(k=>p.work[k]>0).join(" "))}">${p.image?`<img class="entity-image pal-image" src="/assets/pals/${encodeURIComponent(p.id)}.png" alt="${esc(palName(p))}" loading="lazy" width="160" height="160">`:`<div class="pal-image item-fallback" aria-hidden="true">◇</div>`}<div class="pal-card-body"><div class="pal-number">#${p.dex}${p.variant?"B":""}</div><h2><a href="${href(`/pals/${encodeURIComponent(p.id)}`)}" data-link>${esc(palName(p))}</a></h2><dl class="pal-stats"><div><dt>${m.hp}</dt><dd>${p.hp}</dd></div><div><dt>${m.attack}</dt><dd>${p.attack}</dd></div><div><dt>${m.defense}</dt><dd>${p.defense}</dd></div><div><dt>${m.rarity}</dt><dd>${p.rarity}</dd></div></dl><div class="work-suitability-list compact-list">${workSuitabilityBadges(p.work,true)}</div></div></article>`}
function palsPage(){const description=`${m.palDex}. ${m.tagline}`;setMeta(m.palDex,description);const pals=[...(data?.pals||[])],sorted=pals.sort((a,b)=>a.dex-b.dex||Number(a.variant)-Number(b.variant)||a.id.localeCompare(b.id)),rarities=[...new Set(pals.map(p=>p.rarity))].sort((a,b)=>a-b),works=[...new Set(pals.flatMap(p=>Object.keys(p.work).filter(k=>p.work[k]>0)))].sort(),workById=new Map((data?.workSuitabilities||[]).map(entry=>[entry.id,entry]));return `${hero(m.palDex,m.palDexBody)}<section class="section"><div class="collection-filters"><label class="collection-search">${m.search}<input id="pal-search" type="search" autocomplete="off"></label><label>${m.rarity}<select id="pal-rarity"><option value="">${m.choose}</option>${rarities.map(v=>`<option value="${v}">${v}</option>`).join("")}</select></label><label>${m.work}<select id="pal-work"><option value="">${m.choose}</option>${works.map(id=>{const work=workById.get(id),label=work?.names[locale]||work?.names[defaultLocale]||id;return `<option value="${esc(id)}">${esc(label)}</option>`}).join("")}</select></label><button class="button search-clear" data-clear-search="pal" aria-label="${m.remove}">×</button></div><p id="pal-count" role="status">${sorted.length.toLocaleString(locale)} ${m.results}</p><p id="pal-empty" class="empty-compact" hidden>${m.noResult}</p><div class="pal-grid">${sorted.map(palCard).join("")}</div></section>`}
function itemVisual(item:Item,{detail=false}={}){const target=item.unlocksItemId?itemData?.items.find(candidate=>candidate.id===item.unlocksItemId):undefined,base=item.image?`<img class="${detail?"detail-image":"entity-image item-image"}" src="/assets/items/${encodeURIComponent(item.id)}.webp" alt="${esc(itemName(item))}" ${detail?"":'loading="lazy" width="96" height="96"'}>`:`<span class="${detail?"detail-image ":""}item-image item-fallback" aria-hidden="true">◇</span>`;return target?.image?`<span class="blueprint-visual${detail?" detail":""}">${base}<img class="blueprint-product" src="/assets/items/${encodeURIComponent(target.id)}.webp" alt="" loading="lazy"></span>`:base}
